import strokeData from '../assets/data/kanji/strokes.json';
import { describeCollision, glossCollisions } from './tools/gloss-rules';

/**
 * The stroke data is generated by tools/build-stroke-data.mjs, which fails
 * loudly on a bad character. These are the guards for the file that is actually
 * shipped, so a hand-edit or a half-finished regeneration cannot slip through.
 */
describe('the shipped stroke data', () => {
  it('has the whole deck: all six school years, in full', () => {
    expect(strokeData.characters).toHaveLength(1026);
    expect(strokeData.characters.filter(c => c.grade === 1)).toHaveLength(80);
    expect(strokeData.characters.filter(c => c.grade === 2)).toHaveLength(160);
    expect(strokeData.characters.filter(c => c.grade === 3)).toHaveLength(200);
    // 202, not 200: the 2020 学年別漢字配当表 revision added the prefecture
    // kanji to grade 4.
    expect(strokeData.characters.filter(c => c.grade === 4)).toHaveLength(202);
    expect(strokeData.characters.filter(c => c.grade === 5)).toHaveLength(193);
    expect(strokeData.characters.filter(c => c.grade === 6)).toHaveLength(191);
    expect(strokeData.viewBox).toBe(109);
  });

  /**
   * The deck is in learning order: nobody should be asked to write 休 before
   * having written 人 and 木. Components come from KanjiVG's decomposition,
   * limited to kanji the deck itself teaches.
   */
  it('teaches every kanji after the parts it is built from', () => {
    const position = new Map(strokeData.characters.map((character, index) => [character.kanji, index]));

    const misplaced = strokeData.characters.flatMap(character =>
      character.components
        .filter(part => (position.get(part) ?? Infinity) > (position.get(character.kanji) ?? 0))
        .map(part => `${character.kanji} before its part ${part}`),
    );

    expect(misplaced).toEqual([]);
  });

  it('has every kanji only once', () => {
    const kanji = strokeData.characters.map(character => character.kanji);

    expect(new Set(kanji).size).toBe(kanji.length);
  });

  it('numbers every stroke of every kanji', () => {
    const mismatched = strokeData.characters
      .filter(character => character.numbers.length !== character.strokes.length)
      .map(character => character.kanji);

    expect(mismatched).toEqual([]);
  });

  it('keeps every stroke number inside the square', () => {
    const outside = strokeData.characters
      .flatMap(character => character.numbers.map(number => ({ kanji: character.kanji, ...number })))
      .filter(number => number.x < 0 || number.x > 109 || number.y < 0 || number.y > 109);

    expect(outside).toEqual([]);
  });

  /**
   * The ranks the practice list can be sorted by. A missing JLPT level is a
   * fact about the lists - they skip a few kanji - but the skipped ones are
   * known by name, so a regeneration that quietly loses the levels cannot
   * pass as one that found four gaps.
   */
  it('carries a JLPT level for every kanji the lists have', () => {
    const outside = strokeData.characters
      .filter(character => character.jlpt === null)
      .map(character => character.kanji);

    expect(outside.sort()).toEqual(
      ['分', '里', '身', '畑', '的', '無', '岡', '阪', '埼', '阜', '茨', '栃', '可', '孝'].sort(),
    );
    for (const character of strokeData.characters) {
      if (character.jlpt !== null) {
        expect(character.jlpt).toBeGreaterThanOrEqual(1);
        expect(character.jlpt).toBeLessThanOrEqual(5);
      }
    }
  });

  /**
   * Every kanji of the six school years appears in the counted
   * corpora and so holds a frequency rank; a kanji the corpora never saw
   * would go null. A rank is a position, so no two kanji share one.
   */
  it('ranks every kanji by frequency, each rank its own', () => {
    const ranks = strokeData.characters.map(character => character.freq);

    expect(ranks.every(rank => Number.isInteger(rank) && rank >= 1)).toBe(true);
    expect(new Set(ranks).size).toBe(ranks.length);
  });

  /**
   * The parts a character divides into, for the decomposition shown on its own
   * page. Every stroke has to belong to one of them, or the division is only
   * part of the character. Two parts may claim the same stroke, which is not a
   * mistake: 重's long vertical is the last stroke of its 千 and the middle of
   * its 里, and 様's is the spine of both its 羊 and its 氺. Characters are
   * written that way.
   */
  it('divides a character into parts that account for all of it', () => {
    const divided = strokeData.characters.filter(character => 'parts' in character);

    expect(divided.length).toBe(952);
    for (const character of divided) {
      const parts = (character as { parts: { strokes: number[]; element?: string }[] }).parts;
      expect(parts.length).toBeGreaterThanOrEqual(2);
      // A division nothing can be named in says no more than the stroke count.
      expect(parts.some(part => part.element)).toBe(true);

      const covered = parts.flatMap(part => {
        expect(part.strokes.length).toBeGreaterThan(0);
        expect(Math.min(...part.strokes)).toBeGreaterThanOrEqual(1);
        expect(Math.max(...part.strokes)).toBeLessThanOrEqual(character.strokes.length);
        return part.strokes;
      });

      expect(new Set(covered).size).toBe(character.strokes.length);
    }
  });

  /**
   * A part that names a deck kanji is a link to that kanji's own page, and the
   * lesson order has to have taught it first - which componentsOf already
   * guarantees for the parts it finds, but a part is free to name a kanji
   * componentsOf drops as etymology only.
   */
  /**
   * Every name is a shape somebody can read. KanjiVG falls back to a filing
   * code where Unicode has no character for a shape - 原's 白 and 小 are one
   * shape between them and that shape is "CDP-8BC4" - and a tile is no place
   * for it.
   */
  it('never writes a filing code where a shape should be', () => {
    const shape = /^[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}\u2E80-\u2FFF\u31C0-\u31EF\u3005\u303B]+$/u;

    const codes = strokeData.characters.flatMap(character =>
      ((character as { parts?: { element?: string; unitOf?: string }[] }).parts ?? [])
        .flatMap(part => [part.element, part.unitOf])
        .filter((name): name is string => !!name && !shape.test(name))
        .map(name => `${character.kanji}: ${name}`),
    );

    expect(codes).toEqual([]);
  });

  /**
   * A box around a run of tiles says they are one shape between them, and the
   * name under it says which. Without a name there is nothing for it to say,
   * and 三 would be boxed as a 一 over a pair of 一.
   */
  it('names every shape it boxes a run of parts as', () => {
    const nameless = strokeData.characters.flatMap(character =>
      ((character as { parts?: { unit?: number; unitOf?: string }[] }).parts ?? [])
        .filter(part => part.unit && !part.unitOf)
        .map(() => character.kanji),
    );

    expect(nameless).toEqual([]);
  });

  /**
   * 士 and 土 are two kanji a learner has to keep apart, and KanjiVG files the
   * top of 売 and 声 under 土 as a variant. Following that would put the page
   * on the wrong side of the one difference that matters, so the shape is shown
   * as the 士 it is written as and links nowhere.
   */
  it('never sends a 士 to the page for 土', () => {
    const merged = strokeData.characters.flatMap(character =>
      ((character as { parts?: { element?: string; kanji?: string }[] }).parts ?? [])
        .filter(part => part.element === '士' && part.kanji)
        .map(part => `${character.kanji}: 士 links to ${part.kanji}`),
    );

    expect(merged).toEqual([]);
    const builtOnEarth = strokeData.characters
      .filter(character => (character.components as string[]).includes('土'))
      .map(character => character.kanji);

    expect(builtOnEarth).not.toContain('売');
    expect(builtOnEarth).not.toContain('声');
  });

  it('only points a part at a kanji the deck has already taught', () => {
    const position = new Map(strokeData.characters.map((character, index) => [character.kanji, index]));

    const late = strokeData.characters.flatMap((character, index) =>
      ((character as { parts?: { kanji?: string }[] }).parts ?? [])
        .filter(part => part.kanji && (position.get(part.kanji) ?? Infinity) > index)
        .map(part => `${character.kanji} links back to ${part.kanji}`),
    );

    expect(late).toEqual([]);
  });

  it('has a meaning in both languages and at least one stroke', () => {
    for (const character of strokeData.characters) {
      expect(character.strokes.length).toBeGreaterThan(0);
      expect(character.meaning.en).toBeTruthy();
      expect(character.meaning.nl).toBeTruthy();
    }
  });

  /**
   * A review shows the meaning and asks for the character, so a word two kanji
   * share must never be the whole question. What counts as sharing it safely -
   * distinct senses in brackets, or synonyms where each keeps a word of its
   * own - is `tools/gloss-rules.mjs`, which `tools/check-glosses.mjs` asks the
   * same question of the deck source before a regeneration. One rule, two
   * callers: a second copy of that list would drift within a month.
   */
  it('never gives the same meaning to two kanji', () => {
    for (const language of ['en', 'nl'] as const) {
      const failed = glossCollisions(strokeData.characters, language).map(describeCollision);

      expect(failed).toEqual([]);
    }
  });

  /**
   * The radical pages: recurring shapes with strokes, a name in both
   * languages, and enough tiles to be worth a page. The four-tile floor is
   * the policy, not an accident of the data - a shape appearing twice does
   * not need a page, and this is where that decision is held.
   */
  it('gives every radical strokes, both names, and four tiles to link from', () => {
    const radicals = (strokeData as unknown as {
      radicals: { shape: string; name: { en: string; nl: string }; formOf?: string;
        strokes: string[]; numbers: unknown[] }[];
    }).radicals;

    // The meat-moon: written as 月, filed under ⺼, never linked as the moon.
    const flesh = strokeData.characters.filter(character =>
      (character as { parts?: { radical?: string }[] }).parts?.some(part => part.radical === '⺼'));
    expect(flesh.length).toBeGreaterThanOrEqual(17);
    for (const character of flesh) {
      const parts = (character as { parts?: { radical?: string; kanji?: string; element?: string }[] }).parts ?? [];
      for (const part of parts.filter(part => part.radical === '⺼')) {
        expect(part.kanji).toBeUndefined();
        expect(part.element).toBe('月');
      }
    }

    expect(radicals.length).toBe(34);
    expect(new Set(radicals.map(radical => radical.shape)).size).toBe(radicals.length);

    const deck = new Set(strokeData.characters.map(character => character.kanji));
    for (const radical of radicals) {
      expect(radical.strokes.length).toBeGreaterThan(0);
      expect(radical.numbers.length).toBe(radical.strokes.length);
      expect(radical.name.en).toBeTruthy();
      expect(radical.name.nl).toBeTruthy();
      if (radical.formOf) {
        expect(deck.has(radical.formOf)).toBe(true);
      }
      const tiles = strokeData.characters.reduce(
        (total, character) =>
          total +
          ((character as { parts?: { element?: string; radical?: string }[] }).parts?.filter(
            part => (part.radical ?? part.element) === radical.shape,
          ).length ?? 0),
        0,
      );
      expect(tiles, `${radical.shape} carries ${tiles} tiles`).toBeGreaterThanOrEqual(4);
    }
  });

  it('credits KanjiVG, whose licence asks for it', () => {
    expect(strokeData.source).toBe('KanjiVG');
    expect(strokeData.license).toBe('CC BY-SA 3.0');
  });
});
